<span class="line"><span style="color:#E06C75;font-style:italic;">            yearly_seasonality</span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;">self</span><span style="color:#ABB2BF;">.yearly_seasonality,</span></span>
